import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Benchmarks vs Strauss PHP","description":"Strauss-RS is 24x to 28x faster than Strauss PHP on one worker and up to 139x faster on 12, with far less memory. Includes the method and how to reproduce.","frontmatter":{"title":"Benchmarks vs Strauss PHP","description":"Strauss-RS is 24x to 28x faster than Strauss PHP on one worker and up to 139x faster on 12, with far less memory. Includes the method and how to reproduce.","image":"/social/benchmarks.jpg","imageAlt":"Benchmark results comparing Strauss-RS with Strauss PHP"},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md"}`),a={name:`benchmarks.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to “Benchmarks”">​</a></h1><p>These are timings of <code>prefix</code> for Strauss PHP and Strauss-RS on four projects of different sizes. They were taken on one machine, so treat them as a guide to the size of the difference. Your results will vary with your hardware, your project and your disk.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to “Results”">​</a></h2><p>Each time is the median of several runs: seven for the small and medium projects, three for the large and extra large ones.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Project</th><th style="text-align:right;">Workers</th><th style="text-align:right;">Strauss PHP</th><th style="text-align:right;">Strauss-RS</th><th style="text-align:right;">Speedup</th><th style="text-align:right;">PHP peak memory</th><th style="text-align:right;">RS peak memory</th></tr></thead><tbody><tr><td style="text-align:left;">small</td><td style="text-align:right;">1</td><td style="text-align:right;">625.4 ms</td><td style="text-align:right;">22.8 ms</td><td style="text-align:right;">27.4x</td><td style="text-align:right;">70 MiB</td><td style="text-align:right;">9.5 MiB</td></tr><tr><td style="text-align:left;">small</td><td style="text-align:right;">12</td><td style="text-align:right;">831.3 ms</td><td style="text-align:right;">9.1 ms</td><td style="text-align:right;">91.0x</td><td style="text-align:right;">411 MiB</td><td style="text-align:right;">11.7 MiB</td></tr><tr><td style="text-align:left;">medium</td><td style="text-align:right;">1</td><td style="text-align:right;">1.11 s</td><td style="text-align:right;">46.5 ms</td><td style="text-align:right;">24.0x</td><td style="text-align:right;">83 MiB</td><td style="text-align:right;">13.1 MiB</td></tr><tr><td style="text-align:left;">medium</td><td style="text-align:right;">12</td><td style="text-align:right;">1.38 s</td><td style="text-align:right;">16.2 ms</td><td style="text-align:right;">85.5x</td><td style="text-align:right;">599 MiB</td><td style="text-align:right;">19.5 MiB</td></tr><tr><td style="text-align:left;">large</td><td style="text-align:right;">1</td><td style="text-align:right;">18.72 s</td><td style="text-align:right;">761.3 ms</td><td style="text-align:right;">24.6x</td><td style="text-align:right;">259 MiB</td><td style="text-align:right;">81.6 MiB</td></tr><tr><td style="text-align:left;">large</td><td style="text-align:right;">12</td><td style="text-align:right;">16.84 s</td><td style="text-align:right;">188.7 ms</td><td style="text-align:right;">89.3x</td><td style="text-align:right;">1,291 MiB</td><td style="text-align:right;">97.7 MiB</td></tr><tr><td style="text-align:left;">xlarge</td><td style="text-align:right;">1</td><td style="text-align:right;">42.26 s</td><td style="text-align:right;">1.50 s</td><td style="text-align:right;">28.2x</td><td style="text-align:right;">990 MiB</td><td style="text-align:right;">336.2 MiB</td></tr><tr><td style="text-align:left;">xlarge</td><td style="text-align:right;">12</td><td style="text-align:right;">55.05 s</td><td style="text-align:right;">395.6 ms</td><td style="text-align:right;">139.1x</td><td style="text-align:right;">5,556 MiB</td><td style="text-align:right;">405.4 MiB</td></tr></tbody></table><ul><li>Small: monolog</li><li>Medium: guzzle + flysystem + finder</li><li>Large: laravel/framework</li><li>X-Large: aws-sdk-php</li></ul><h2 id="how-they-were-run" tabindex="-1">How they were run <a class="header-anchor" href="#how-they-were-run" aria-label="Permalink to “How they were run”">​</a></h2><ul><li>Wall time for <code>prefix</code> command</li><li>Median of 5 runs after 1 warm-up, from a clean output directory each time.</li><li>Both tools were given the worker count explicitly (1 against 1, 12 against 12).</li><li>Memory is peak total across all processes, sampled on Linux.</li><li>Strauss PHP 0.31.1 on PHP 8.4.23 (static CLI build, no OPcache, no memory limit).</li><li>Strauss-RS release build.</li><li>Intel i5-10600 (12 threads), 32 GB RAM.</li><li>All projects with locked dependencies.</li></ul><h2 id="what-to-keep-in-mind" tabindex="-1">What to keep in mind <a class="header-anchor" href="#what-to-keep-in-mind" aria-label="Permalink to “What to keep in mind”">​</a></h2><ul><li>These measure the <code>prefix</code> step. A Composer install and your own build steps take the same time with either tool.</li></ul><h2 id="how-to-reproduce-benchmarks" tabindex="-1">How to reproduce benchmarks <a class="header-anchor" href="#how-to-reproduce-benchmarks" aria-label="Permalink to “How to reproduce benchmarks”">​</a></h2><p>Clone the repo from GitHub, then run the following commands</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Setup downloads the pinned Strauss PHP 0.31.1 phar and runs composer install for each project. run has these options:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--project &lt;NAME&gt;</code></td><td>Only run this project. Can be given more than once. By default every project in <code>benchmark.json</code> is run.</td></tr><tr><td><code>--tool &lt;rs|php&gt;</code></td><td>Only run this tool. Can be given more than once. By default both are run.</td></tr><tr><td><code>--runs &lt;N&gt;</code></td><td>How many timed runs of each. The default is 5.</td></tr><tr><td><code>--warmup &lt;N&gt;</code></td><td>How many runs to throw away first. The default is 1.</td></tr><tr><td><code>--workers &lt;N&gt;</code></td><td>How many workers in the runs with many. Must be 2 or more. The default is one per CPU.</td></tr><tr><td><code>--php &lt;PATH&gt;</code></td><td>The PHP binary that runs Strauss PHP and checks the output. The default is <code>php</code> from your <code>PATH</code>.</td></tr><tr><td><code>--json &lt;FILE&gt;</code></td><td>Write the results, and what they were measured on, to this JSON file.</td></tr><tr><td><code>--keep</code></td><td>Leave the last output in place, instead of deleting it.</td></tr><tr><td><code>--no-check</code></td><td>Don&#39;t parse the output with PHP.</td></tr><tr><td><code>--no-tree-memory</code></td><td>Don&#39;t take the extra run that adds up the memory of every process.</td></tr><tr><td><code>--allow-debug</code></td><td>Run even though this is a debug build. The times mean nothing in a debug build.</td></tr></tbody></table>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};